$('sizePreset').onchange=()=>{const preset=socialSizePresets.find(p=>p.id===$('sizePreset').value);if(!preset){clearSizePreset();return}const previousExtent=Math.min(outputWidth,outputHeight);outputWidth=preset.width;outputHeight=preset.height;$('outputWidth').value=outputWidth;$('outputHeight').value=outputHeight;$('squareLock').checked=outputWidth===outputHeight;const ratio=Math.min(outputWidth,outputHeight)/previousExtent;titleFontPixels*=ratio;titleIconPixels*=ratio;syncHeadingSizeControls();$('sizeNotice').textContent='';$('sizePresetNote').textContent=preset.platform+' '+preset.basis+'：'+preset.w+' × '+preset.h+'px'+'（2026年10月13日確認）'+(preset.note?'。'+preset.note:'');$('sizePresetSource').href=preset.source;$('sizePresetSource').hidden=false;render()};

function renderSizePresetOptions(){const select=$('sizePreset'),previous=select.value,platform=$('sizePlatform').value;select.replaceChildren();const custom=document.createElement('option');custom.value='custom';custom.textContent='カスタム（手動で設定）';select.append(custom);const groups=new Map();socialSizePresets.filter(p=>platform==='all'||p.platform===platform).forEach(p=>{const label=p.platform+'｜'+p.category;if(!groups.has(label)){const group=document.createElement('optgroup');group.label=label;groups.set(label,group);select.append(group)}const option=document.createElement('option');option.value=p.id;option.textContent=p.label+'：'+p.width+' × '+p.height+'px';groups.get(label).append(option)});if(socialSizePresets.some(p=>p.id===previous&&(platform==='all'||p.platform===platform)))select.value=previous;else{select.value='custom';clearSizePreset()}}
$('sizePlatform').onchange=renderSizePresetOptions;renderSizePresetOptions();

// Use the browser's actual line breaks and glyph positions instead of wrapping again.
function renderedTextLines(el){const style=getComputedStyle(el),tolerance=Math.max(1,parseFloat(style.fontSize)*.2),lines=[],walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const value=node.textContent,segments=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(value)].map(s=>({text:s.segment,index:s.index})):Array.from(value).reduce((list,text)=>{const index=list.length?list[list.length-1].index+list[list.length-1].text.length:0;list.push({text,index});return list},[]);for(const segment of segments){const range=document.createRange();range.setStart(node,segment.index);range.setEnd(node,segment.index+segment.text.length);const rect=range.getBoundingClientRect();if(!rect.height||segment.text==='\n')continue;let line=lines.find(l=>Math.abs(l.top-rect.top)<tolerance);if(!line){line={text:'',left:rect.left,right:rect.right,top:rect.top,height:rect.height};lines.push(line)}line.text+=segment.text;line.left=Math.min(line.left,rect.left);line.right=Math.max(line.right,rect.right);line.height=Math.max(line.height,rect.height)}}return lines.sort((a,b)=>a.top-b.top)}
function drawRenderedText(ctx,el,box,scale){if(!el.textContent.trim())return;const style=getComputedStyle(el),fontSize=parseFloat(style.fontSize)*scale;ctx.save();ctx.fillStyle=style.color;ctx.font=style.fontStyle+' '+style.fontWeight+' '+fontSize+'px '+style.fontFamily;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.direction=style.direction;if('fontKerning' in ctx)ctx.fontKerning=style.fontKerning;if('letterSpacing' in ctx)ctx.letterSpacing=(parseFloat(style.letterSpacing)||0)*scale+'px';const metrics=ctx.measureText('Mgあ'),ascent=metrics.fontBoundingBoxAscent||fontSize*.8,descent=metrics.fontBoundingBoxDescent||fontSize*.2;for(const line of renderedTextLines(el)){const x=(line.left-box.left)*scale,y=(line.top-box.top)*scale+ascent+(line.height*scale-ascent-descent)/2,width=(line.right-line.left)*scale;if(width>0)ctx.fillText(line.text,x,y,width+.25*scale)}ctx.restore()}
function fitOutputPreviewDialog(){if(!outputPreviewCanvas||!$('outputPreviewDialog').open)return;const dialog=$('outputPreviewDialog'),area=dialog.querySelector('.output-preview-image-area'),ratio=outputPreviewCanvas.width/outputPreviewCanvas.height,maxWidth=Math.max(240,window.innerWidth-32),maxHeight=Math.max(180,window.innerHeight-32),padding=window.innerWidth<=650?32:48;dialog.style.width=Math.min(maxWidth,Math.max(Math.min(340,maxWidth),Math.min(outputPreviewCanvas.width,(maxHeight-160)*ratio)+padding))+'px';for(let i=0;i<2;i++){const style=getComputedStyle(dialog),visible=[...dialog.children].filter(e=>getComputedStyle(e).display!=='none'),chrome=visible.filter(e=>e!==area).reduce((sum,e)=>sum+e.getBoundingClientRect().height,0)+parseFloat(style.paddingTop)+parseFloat(style.paddingBottom)+parseFloat(style.borderTopWidth)+parseFloat(style.borderBottomWidth)+(visible.length-1)*parseFloat(style.rowGap||0),availableWidth=Math.max(1,dialog.clientWidth-padding),height=Math.max(1,Math.min(outputPreviewCanvas.height,maxHeight-chrome,availableWidth/ratio));dialog.style.width=Math.min(maxWidth,Math.max(Math.min(340,maxWidth),height*ratio+padding))+'px';area.style.height=height+'px';dialog.style.height=Math.min(maxHeight,chrome+height)+'px'}}
window.addEventListener('resize',()=>{if($('outputPreviewDialog').open)fitOutputPreviewDialog()});

for(const type of ['dragenter','dragover'])$('cropUpload').addEventListener(type,e=>{if(!isFileDrag(e))return;e.preventDefault();e.stopPropagation();e.dataTransfer.dropEffect='copy';$('cropUpload').classList.add('drag')});$('cropUpload').addEventListener('dragleave',()=>$('cropUpload').classList.remove('drag'));$('cropUpload').addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();e.stopPropagation();$('cropUpload').classList.remove('drag');$('cropUploadNotice').textContent=e.dataTransfer.files.length>1?'背景には1枚の画像を使用します。最初の画像を選択しました。':'';setBackground(e.dataTransfer.files)});


const mobileLayout=window.matchMedia('(max-width:650px)');
const settingsPane=document.querySelector('.workspace>aside'),usagePane=document.querySelector('.usage-guide');
const settingsAnchor=document.createComment('settings position'),usageAnchor=document.createComment('usage position');
settingsPane.before(settingsAnchor);usagePane.before(usageAnchor);
function syncMobileMenu(){if(mobileLayout.matches){$('mobileMenuContent').append(usagePane);$('mobileSettingsContent').append(settingsPane)}else{if($('mobileMenuDialog').open)$('mobileMenuDialog').close();if($('mobileSettingsDialog').open)$('mobileSettingsDialog').close();settingsPane.hidden=false;usagePane.hidden=false;settingsAnchor.after(settingsPane);usageAnchor.after(usagePane)}render()}
$('mobileMenuButton').onclick=()=>{showMobileSection(null);$('mobileMenuDialog').showModal();$('mobileMenuButton').setAttribute('aria-expanded','true');$('mobileMenuContent').scrollTop=0;$('mobileMenuClose').focus()};
$('mobileMenuClose').onclick=()=>$('mobileMenuDialog').close();
$('mobileMenuDialog').addEventListener('close',()=>{$('mobileMenuButton').setAttribute('aria-expanded','false');if(mobileLayout.matches)$('mobileMenuButton').focus()});
$('mobileMenuDialog').addEventListener('click',e=>{if(e.target===$('mobileMenuDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('mobileUsageLink').onclick=()=>showMobileSection('usage');
mobileLayout.addEventListener('change',syncMobileMenu);syncMobileMenu();

function showMobileSection(section){const detailed=!!section;usagePane.hidden=section!=='usage';settingsPane.hidden=section!=='settings';$('mobileMenuContent').hidden=!detailed;$('mobileMenuBack').hidden=!detailed;document.querySelector('.mobile-menu-nav').hidden=detailed;$('mobileMenuTitle').textContent=section==='usage'?'使い方':section==='settings'?'画像設定':'メニュー';$('mobileMenuContent').scrollTop=0;if(detailed)$('mobileMenuBack').focus()}
$('mobileMenuBack').onclick=()=>{showMobileSection(null);$('mobileUsageLink').focus()};

$('mobileSettingsClose').onclick=()=>$('mobileSettingsDialog').close();$('mobileSettingsDialog').addEventListener('close',()=>{if(mobileLayout.matches)$('mobileMenuButton').focus()});

function positionHeadingSettingsButton(){positionMobileSettingsRail();if(window.matchMedia('(max-width:650px)').matches){for(const id of ['headingSettingsButton','photoSettingsButton'])$(id)?.style.removeProperty('top');return}const button=$('headingSettingsButton');if(!button)return;const stage=$('previewStage').getBoundingClientRect(),title=$('canvasTitle').getBoundingClientRect();button.style.top=Math.max(0,title.top-stage.top+(title.height-44)/2)+'px';const photo=$('photoSettingsButton'),area=$('photoArea').getBoundingClientRect();if(photo)photo.style.top=Math.max(0,area.top-stage.top)+'px'}
function openHeadingSettings(){if($('mobileMenuDialog').open)$('mobileMenuDialog').close();$('mobileSettingsContent').append(settingsPane);settingsPane.hidden=false;for(const group of settingsPane.querySelectorAll(':scope>.settings-group'))group.hidden=group.id!=='headingSettings';$('headingSettings').open=true;$('mobileSettingsTitle').textContent='見出し設定';$('mobileSettingsDialog').showModal();$('mobileSettingsContent').scrollTop=0;$('mobileSettingsClose').focus()}
$('headingSettingsButton').onclick=openHeadingSettings;
$('mobileSettingsOk').onclick=()=>$('mobileSettingsDialog').close();
$('mobileSettingsDialog').addEventListener('close',()=>{for(const group of settingsPane.querySelectorAll(':scope>.settings-group'))group.hidden=false;$('mobileSettingsTitle').textContent='画像設定';if(!mobileLayout.matches){settingsPane.hidden=false;settingsAnchor.after(settingsPane)}render()});
window.addEventListener('resize',positionHeadingSettingsButton);positionHeadingSettingsButton();


const movableSettingsDialog=$('mobileSettingsDialog'),settingsDragHandle=movableSettingsDialog.querySelector('.mobile-menu-header');let settingsDrag=null;
function keepSettingsOnScreen(){if(!movableSettingsDialog.open||!movableSettingsDialog.dataset.moved)return;const r=movableSettingsDialog.getBoundingClientRect();movableSettingsDialog.style.left=Math.max(8,Math.min(r.left,innerWidth-r.width-8))+'px';movableSettingsDialog.style.top=Math.max(8,Math.min(r.top,innerHeight-60))+'px'}
settingsDragHandle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,input,select'))return;const r=movableSettingsDialog.getBoundingClientRect();settingsDrag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top};movableSettingsDialog.style.transform='none';movableSettingsDialog.style.left=r.left+'px';movableSettingsDialog.style.top=r.top+'px';movableSettingsDialog.dataset.moved='true';settingsDragHandle.setPointerCapture(e.pointerId);movableSettingsDialog.classList.add('is-moving');e.preventDefault()});
settingsDragHandle.addEventListener('pointermove',e=>{if(!settingsDrag||e.pointerId!==settingsDrag.id)return;const r=movableSettingsDialog.getBoundingClientRect();movableSettingsDialog.style.left=Math.max(8,Math.min(settingsDrag.left+e.clientX-settingsDrag.x,innerWidth-r.width-8))+'px';movableSettingsDialog.style.top=Math.max(8,Math.min(settingsDrag.top+e.clientY-settingsDrag.y,innerHeight-r.height-8))+'px'});
function endSettingsDrag(e){if(!settingsDrag||e.pointerId!==settingsDrag.id)return;settingsDrag=null;movableSettingsDialog.classList.remove('is-moving');if(settingsDragHandle.hasPointerCapture(e.pointerId))settingsDragHandle.releasePointerCapture(e.pointerId)}
settingsDragHandle.addEventListener('pointerup',endSettingsDrag);settingsDragHandle.addEventListener('pointercancel',endSettingsDrag);
movableSettingsDialog.addEventListener('close',()=>{settingsDrag=null;movableSettingsDialog.classList.remove('is-moving');delete movableSettingsDialog.dataset.moved;for(const property of ['left','top','transform'])movableSettingsDialog.style.removeProperty(property)});
window.addEventListener('resize',keepSettingsOnScreen);new ResizeObserver(keepSettingsOnScreen).observe(movableSettingsDialog);

const singleSettingsGroup=[...settingsPane.querySelectorAll(':scope>.settings-group')].find(group=>group.querySelector('summary')?.textContent.trim()==='画像単体');
$('photoSettingsButton').onclick=()=>{if($('mobileMenuDialog').open)$('mobileMenuDialog').close();$('mobileSettingsContent').append(settingsPane);settingsPane.hidden=false;for(const group of settingsPane.querySelectorAll(':scope>.settings-group'))group.hidden=group!==singleSettingsGroup;singleSettingsGroup.open=true;$('mobileSettingsTitle').textContent='画像単体';$('mobileSettingsDialog').showModal();$('mobileSettingsContent').scrollTop=0;$('mobileSettingsClose').focus()};

$('backgroundDeleteButton').onclick=()=>{if(bg)$('backgroundDeleteDialog').showModal()};
$('backgroundDeleteCancel').onclick=()=>$('backgroundDeleteDialog').close();
$('backgroundDeleteDialog').addEventListener('close',()=>{if($('cropDialog').open&&!$('backgroundDeleteButton').hidden)$('backgroundDeleteButton').focus()});
$('backgroundDeleteConfirm').onclick=()=>{if(bg)$('bgRemove').click();$('backgroundDeleteDialog').close();prepareCrop();$('cropUpload').focus();$('orderStatus').textContent='背景画像を削除しました。'};

function releaseBackgroundUrl(url){if(backgroundSession)pendingBackgroundUrls.add(url);else URL.revokeObjectURL(url)}
$('cropDialog').addEventListener('close',()=>{if(!backgroundSession)return;const session=backgroundSession;if(!session.committed){if(bg&&bg.url!==session.image?.url)pendingBackgroundUrls.add(bg.url);bg=session.image;mode(session.mode);$('orderStatus').textContent='背景の変更をキャンセルしました。'}$('bgDetails').hidden=!bg;if(bg){$('bgName').textContent=bg.name;$('bgThumb').src=bg.url}else{$('bgName').textContent='';$('bgThumb').removeAttribute('src')}for(const url of pendingBackgroundUrls)if(url!==bg?.url)URL.revokeObjectURL(url);pendingBackgroundUrls.clear();backgroundSession=null;render()});

$('overallSettingsButton').onclick=()=>{if($('mobileMenuDialog').open)$('mobileMenuDialog').close();$('mobileSettingsContent').append(settingsPane);settingsPane.hidden=false;const overall=settingsPane.querySelector(':scope>.settings-group');for(const group of settingsPane.querySelectorAll(':scope>.settings-group'))group.hidden=group!==overall;overall.open=true;$('mobileSettingsTitle').textContent='画像全体設定';$('mobileSettingsDialog').showModal();$('mobileSettingsContent').scrollTop=0;$('mobileSettingsClose').focus()};
$('mobileAddImageButton').onclick=()=>$('files').click();

const LEGAL_PAGE_URLS={privacy:'https://www.yahoo.co.jp/',terms:'https://www.yahoo.co.jp/'};
function openSiteInfo(kind){if($('mobileMenuDialog').open)$('mobileMenuDialog').close();const version=kind==='version',title=version?'バージョン情報':kind==='privacy'?'プライバシーポリシー':'利用規約';$('siteInfoTitle').textContent=title;$('versionInfo').hidden=!version;$('legalInfo').hidden=version;$('siteInfoDialog').classList.toggle('version-dialog',version);if(!version){$('legalFrame').src=LEGAL_PAGE_URLS[kind];$('legalFrame').title=title;$('legalExternalLink').href=LEGAL_PAGE_URLS[kind]}$('siteInfoDialog').showModal();$('siteInfoClose').focus()}
document.querySelectorAll('[data-info]').forEach(button=>button.onclick=()=>openSiteInfo(button.dataset.info));
for(const id of ['siteInfoClose','siteInfoOk'])$(id).onclick=()=>$('siteInfoDialog').close();
$('siteInfoDialog').addEventListener('close',()=>{$('legalFrame').removeAttribute('src')});

function positionMobileSettingsRail(){const rail=document.getElementById('previewSettingsRail');if(!rail)return;if(!window.matchMedia('(max-width:650px)').matches){rail.style.removeProperty('top');return}const stage=document.getElementById('previewStage').getBoundingClientRect(),square=document.getElementById('square').getBoundingClientRect();rail.style.top='0px'}

function fitMobilePreviewHeight(){const stage=$('previewStage');if(!window.matchMedia('(max-width:650px)').matches){stage.style.removeProperty('height');return}const pane=$('rightPane'),article=$('previewDrop'),style=getComputedStyle(article),stageStyle=getComputedStyle(stage),width=Math.max(1,stage.getBoundingClientRect().width-parseFloat(stageStyle.paddingLeft)-parseFloat(stageStyle.paddingRight));const chrome=[...article.children].filter(el=>el!==stage&&getComputedStyle(el).display!=='none').reduce((total,el)=>{const s=getComputedStyle(el);return total+el.getBoundingClientRect().height+parseFloat(s.marginTop||0)+parseFloat(s.marginBottom||0)},0)+parseFloat(style.paddingTop)+parseFloat(style.paddingBottom);const available=Math.max(1,pane.clientHeight-chrome-8),railHeight=$('previewSettingsRail').getBoundingClientRect().height;stage.style.height=Math.max(railHeight,Math.min(width*outputHeight/outputWidth,available))+'px'}
